    37	async fn trace_request(request: Request, next: Next) -> Response {
    38	    let method = request.method().clone();
    39	    let route = request.extensions().get::<MatchedPath>().cloned();
    40	    let health = route
    41	        .as_ref()
    42	        .is_some_and(|path| path.as_str() == "/healthz");
    43	    let route_name = route.as_ref().map(MatchedPath::as_str);
    44	    let span = if health {
    45	        tracing::span!(Level::DEBUG, "http.request",
    46	            http.request.method = %method, http.route = route_name)
    47	    } else {
    48	        tracing::span!(Level::INFO, "http.request",
    49	            http.request.method = %method, http.route = route_name)
    50	    };
    51	    async move {
    52	        let started = Instant::now();
    53	        let response = next.run(request).await;
    54	        complete(
    55	            &response,
    56	            started.elapsed(),
    57	            &method,
    58	            route.as_ref(),
    59	            health,
    60	        );
    61	        response
    62	    }
    63	    .instrument(span)
    64	    .await
    65	}
