    67	fn complete(
    68	    response: &Response,
    69	    latency: Duration,
    70	    method: &axum::http::Method,
    71	    route: Option<&MatchedPath>,
    72	    health: bool,
    73	) {
    74	    let status = response.status();
    75	    let diagnostic = response
    76	        .extensions()
    77	        .get::<ResponseFailure>()
    78	        .map(ResponseFailure::diagnostic);
    79	    let category = response
    80	        .extensions()
    81	        .get::<ResponseFailure>()
    82	        .map(ResponseFailure::category)
    83	        .or_else(|| {
    84	            if status.is_server_error() {
    85	                Some("http.server_error")
    86	            } else if status.is_client_error() {
    87	                Some("http.client_error")
    88	            } else {
    89	                None
    90	            }
    91	        });
    92	    let route = route.map(MatchedPath::as_str);
    93	    macro_rules! emit {
    94	        ($level:ident) => {
    95	            tracing::$level!(
    96	                name: "http.request.completed",
    97	                name = "http.request.completed",
    98	                http.request.method = %method,
    99	                http.route = route,
   100	                http.response.status_code = u64::from(status.as_u16()),
   101	                duration_ms = latency.as_secs_f64() * 1000.0,
   102	                error.type = category,
   103	                error.message = diagnostic,
   104	            )
   105	        };
   106	    }
   107	    if status.is_server_error() {
   108	        emit!(error);
   109	    } else if status.is_client_error() {
   110	        emit!(warn);
   111	    } else if health {
   112	        emit!(debug);
   113	    } else {
   114	        emit!(info);
   115	    }
   116	}
